def expand(items, w):
    out = []
    for it in items:
        if it == 'W':
            out.extend(w)
        elif it[0] == 'R':
            out.extend(SP(it[1]))
        else:
            out.append((it[1], it[2]))
    return tuple(out)


def waypoints(j, b):
    """The full asserted waypoint chain TOP6 -> ... -> TOP7
    (plus the r7 = 2 / r7 = 4 closing waypoints)."""
    r7 = 2 * j - 646578
    w = W(r7, b)
    tail = ((1, 1),) + tuple(SP(b - 1))
    pts = []
    pts.append(('C', TOP6F, 175058, 323286, 2, ((2 * j - 2, 2),) + tail, 1))
    pts.append(('B', TOP6F, 175057, 1, 323286,
                ((2, 2), (2 * j - 2, 2)) + tail, 1))
    pts.append(('C', F7, 323286, 1, 2, ((2 * j - 4, 2),) + tail, 1))
    pts.append(('B', F7, 323286, 1, 4, ((2 * j - 4, 2),) + tail, 1))
    pts.append(('C', F7, 323286, 3, 2, ((2 * j - 6, 2),) + tail, 1))
    pts.append(('C', F7, 0, 3, 2, tuple(SP(323286)) + w, 1))
    for (st, pb, A, g0, s, items, G) in CASCADE53_WPS:
        pts.append((st, pb, A, g0, s, expand(items, w), G))
    if r7 == 2:
        pts.append(('B', (350962,) + TOP7F, 646580, 1, 3,
                    tuple(SP(b - 1)), 1))
    if r7 == 4:
        pts.append(('C', TOP7F, 350961, 646578, 2,
                    ((2, 2), (1, 1)) + tuple(SP(b - 1)), 1))
        pts.append(('B', TOP7F, 350960, 1, 646578,
                    ((2, 2), (2, 2), (1, 1)) + tuple(SP(b - 1)), 1))
        pts.append(('B', (646579, 350961) + TOP7F, 3, 1, 3,
                    tuple(SP(b - 1)), 1))
    return pts


def norm(cfg):
    st, pb, A, g0, s, pairs, G = cfg
    return (st, tuple(pb), A, g0, s, tuple(pairs), G)


def awalk(src, max_steps=12000000):
    """Streaming every-step walker (hsim52's awalk, cap raised):
    yields the target config of EVERY macro/prim step in order,
    then a final ('STATUS', status, cfg, used_rules) tuple."""
    cfg = src
    used = set()
    total = 0
    while total < max_steps:
        if cfg[0] == 'B' and not cfg[5]:
            yield ('STATUS', 'DONE', cfg, used)
            return
        hit = None
        for mac in MACROS:
            hit = mac(cfg)
            if hit:
                break
        if hit:
            cfg = hit[2]
            total += 1
            yield cfg
            continue
        opts = step_all(cfg)
        assert len(opts) == 1, ('walk stuck/branching', cfg)
        used.add(opts[0][0])
        cfg = opts[0][1]
        total += 1
        yield cfg
    yield ('STATUS', 'CAP', cfg, used)


def check_chain(j, b, cap=12000000):
    pts = [norm(p) for p in waypoints(j, b)]
    pos = -1
    status = fin = None
    used = set()
    nrec = 0
    for rec in awalk(TOP6(j, b), max_steps=cap):
        if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
            status, fin, used = rec[1], rec[2], rec[3]
            break
        nrec += 1
        if pos + 1 < len(pts):
            t = pts[pos + 1]
            if rec[0] == t[0] and rec[2] == t[2] and rec[3] == t[3] \
                    and rec[4] == t[4] and (rec == t or norm(rec) == t):
                pos += 1
    assert pos == len(pts) - 1, \
        'j=%d b=%d: waypoint %d missing: %s' \
        % (j, b, pos + 1, fmt(pts[pos + 1]))
    return status, fin, pos, used


def main():
    fails = 0
    used = set()
    # Part 1: full waypoint chain TOP6 -> TOP7, several bands.
    for (j, b) in [(323290, 2), (323290, 3), (323291, 2), (400000, 2),
                   (969870, 2)]:
        try:
            status, fin, pos, u = check_chain(j, b)
            used.update(u)
            print('PASS chain j=%d b=%d: %d waypoints in order, '
                  'walk %s' % (j, b, len(waypoints(j, b)), status),
                  flush=True)
        except AssertionError as e:
            fails += 1
            print('FAIL', e, flush=True)
    # Part 1b: CASCADE53 is tail-general -- junk tail probe.
    w0 = ((7, 2), (1, 1), (3, 2), (1, 2))
    src = ('C', F7, 0, 3, 2, tuple(SP(323286)) + w0, 1)
    top7 = norm(('B', TOP7F, 350961, 1, 646579, w0, 1))
    ok = False
    for rec in swalk(src, max_steps=3000000):
        if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
            break
        if norm(rec) == top7:
            ok = True
            break
    print(('PASS' if ok else 'FAIL'),
          'tail-generality: TOP7 shape reached with junk tail',
          flush=True)
    fails += 0 if ok else 1
    # Part 2: TOP7-closing finals.
    F9 = (350962,) + TOP7F
    F10 = (646579, 350961) + TOP7F
    finals = {
        (323290, 2): (F9, 646581),
        (323290, 3): (F9, 646582),
        (323291, 2): (F10, 4),
        (323291, 3): (F10, 5),
        (323292, 2): (F10, 6),
        (323293, 2): (F10, 8),
        (323293, 3): (F10, 9),
        (400000, 3): (F10, 153423),
        (969870, 2): (F10, 1293162),
    }
    for (j, b), (fr, A) in sorted(finals.items()):
        status = fin = None
        for rec in swalk(TOP6(j, b), max_steps=12000000):
            if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
                status, fin = rec[1], rec[2]
                break
        want = ('B', tuple(fr), A, 1, 2 * b + 1, (), 1)
        ok = status == 'DONE' and norm(fin) == want
        print(('PASS' if ok else 'FAIL'),
              'final j=%d b=%d: %s (want A=%d frame %s)'
              % (j, b, fmt(fin), A, list(fr)), flush=True)
        fails += 0 if ok else 1
    # Part 3: the eighth fence -- r7 >= 1293164 takes DIPGRIND
    # at 646578.
    for (j, b) in [(969871, 2), (969872, 2), (1000000, 2)]:
        r7 = 2 * j - 646578
        g8 = norm(('C', F8, 646578, 3, 2,
                   ((r7 - 6, 2), (1, 1)) + tuple(SP(b - 1)), 1))
        dip8 = norm(('C', F8, 0, 3, 2,
                     tuple(SP(646578))
                     + ((r7 - 1293162, 2), (1, 1)) + tuple(SP(b - 1)), 1))
        seen_g8 = seen_dip8 = False
        for rec in swalk(TOP6(j, b), max_steps=12000000):
            if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
                break
            n = norm(rec)
            if n == g8:
                seen_g8 = True
            elif seen_g8 and n == dip8:
                seen_dip8 = True
                break
        ok = seen_g8 and seen_dip8
        print(('PASS' if ok else 'FAIL'),
              'fence j=%d: GRIND8 then eighth DIPGRIND landing '
              'occur (r7=%d)' % (j, r7), flush=True)
        fails += 0 if ok else 1
    # Part 4: primitive-step audit.
    bad = used - PROVED_RULES
    print(('PASS' if not bad else 'FAIL'),
          'primitive rules used %s all in PROVED_RULES'
          % (sorted(used),), flush=True)
    fails += 0 if not bad else 1
    print()
    print('ALL PHASE 53 CHECKS PASS' if fails == 0
          else '%d FAILURES' % fails)
    return fails


if __name__ == '__main__':
    sys.exit(1 if main() else 0)
